ValidationRule.errorConditionFormula:
AND( ISPICKVAL( Phase__c, 'L - License Review') || ISPICKVAL( Status__c, 'HC - Application Completed') , ISPICKVAL(Type__c, 'LICN - New License') || ISPICKVAL(Type__c, 'LICF - New License After Forfeiture') || ISPICKVAL(Type__c, 'REAC - Reactivation') ,
LicenseType__r.X2ndDependencyRequired__c = true,
OR( ISBLANK (DependentLicense2__c),
NOT(ISPICKVAL(DependentLicense2__r.ActiveInactive__c, 'Active'))
)
)
